<?php use App\Core\Security;?><h4>API Token</h4><form method="post" class="card card-body mb-3"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><div class="row g-2"><div class="col-md-5"><input name="name" class="form-control" placeholder="نام Token" required></div><div class="col-md-5"><input type="datetime-local" name="expires_at" class="form-control"></div><div class="col-md-2"><button class="btn btn-primary w-100">ایجاد</button></div></div></form><table class="table table-bordered"><thead><tr><th>نام</th><th>آخرین استفاده</th><th>انقضا</th><th>وضعیت</th><th></th></tr></thead><tbody><?php foreach($tokens as $r):?><tr><td><?=Security::e($r['name'])?></td><td><?=Security::e($r['last_used_at'])?></td><td><?=Security::e($r['expires_at'])?></td><td><?=$r['is_active']?'فعال':'غیرفعال'?></td><td><?php if($r['is_active']):?><form method="post" action="/pricing/public/api-tokens/<?=(int)$r['id']?>/revoke"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><button class="btn btn-sm btn-outline-danger">لغو</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table>